    startedAt: optionalPlausibleTimestamp(raw.startedAt) ?? 0,
    procStart: typeof raw.procStart === 'string' ? raw.procStart : undefined,
    ...(typeof raw.procStartFt === 'string' && { procStartFt: raw.procStartFt }),
    kind: asRecordKind(raw.kind),
