import { isUsableLocalSocketAddress } from './socketPath.ts'
import { MAX_FORMER_NAMES } from './sessionRegistryState.ts'
import { sliceUnits } from './stringUnits.ts'
import { MAX_SESSION_NAME } from './sessionNameState.ts'
