/** `Ly`: borra las claves de `pid` que no declaran otro dominio, si el pid murió. */
async function deleteDeadPidKeys(
  names: string[],
  dir: string,
  pid: number,
  domain: string,
  remove: (name: string) => Promise<void>,
  deps: RegistrySweepDeps,
): Promise<void> {
  const prefix = `${pid}.`
