  isInteractive: () => boolean
  homedir: () => string
  version: string
  now: () => number
  /** `N()`. */
  storageBackendActive?: () => boolean
  /** `Nh`: el pid es válido y no existe. */
  isProcessGone: (pid: number) => boolean
  /** `ua`: el pid responde a la señal 0. */
  isProcessAlive: (pid: number) => boolean
